    if(state.previewInputId!==preview.id){$('map-delimiter').value=table.delimiter;$('map-skip').value=String(table.skipRows);$('axis-column').value=table.axis===null?'':String(table.axis);$('axis-unit').value='';$('mapping-rows').replaceChildren();addChannel({name:table.responseName,column:table.response??''});state.previewInputId=preview.id;}
    target.append(element('p',`${table.hasHeader?'원본 머리글 포함':'머리글 없음'} · ${table.rows.length}행 미리보기${table.truncated?' · 뒤의 행은 생략':''}. 열 번호는 실제 읽기에 쓰이며 표시 이름은 편집 가능한 제안입니다.`));
    const wrap=element('div',undefined,'table-scroll'),grid=element('table'),head=element('thead'),heading=element('tr');for(const key of table.keys){const cell=element('th');cell.append(element('span',`${table.headers[key]} · ${key}번 열`));cell.append(button('축으로 선택',()=>{$('axis-column').value=String(key);show(`${key}번 열을 축으로 제안했습니다. 이름과 단위를 확인하세요.`);}));cell.append(button('응답으로 선택',()=>{let row=$('mapping-rows').querySelector('tr');if(!row)row=addChannel();row.querySelector('[data-key="column"]').value=String(key);if(!row.querySelector('[data-key="name"]').value)row.querySelector('[data-key="name"]').value=table.headers[key]||`응답 ${key}`;show(`${key}번 열을 응답으로 제안했습니다. 단위·성분·위치를 직접 입력하세요.`);}));heading.append(cell);}head.append(heading);grid.append(head);const body=element('tbody');for(const values of table.rows){const row=element('tr');for(const value of values)row.append(element('td',value));body.append(row);}grid.append(body);wrap.append(grid);target.append(wrap);target.append(element('p','단위·성분·위치는 파일 이름만으로 확정하지 않습니다. 확인 후 아래 버튼으로 결과를 읽으세요.','wb-meta'));
